// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;
    address ownerAddr;

    function setUp() public {
        c = new MyContract();
        // the contract's constructor sets owner = msg.sender, so InvMutTest is owner
        ownerAddr = address(this);
    }

    // Fuzz the amount to transfer and the initial contract balance to create the distinguishing case.
    // If amount > address(c).balance then reference implementation (which transfers amount) will revert,
    // while the mutant (which transfers 0) will not revert. We let the fuzzer find such values.
    function testFuzz_property(uint256 amount, uint256 initialBalance) public {
        vm.assume(initialBalance <= VALUE_CAP);
        // keep domain wide but avoid pointless extremes; ensure initialBalance fits in uint256 (it does)
        // Fund the contract with initialBalance wei
        vm.deal(address(this), initialBalance);
        // send initialBalance into c so c has that balance
        (bool sent, ) = address(c).call{value: initialBalance}(abi.encodeWithSignature(""));
        // now try the transfer as owner (this contract is owner)

        // We want to observe whether sendTo reverts. The universal property:
        // For ALL inputs where amount > address(c).balance, the correct contract's sendTo will revert
        // (because payable(receiver).transfer(amount) will revert on insufficient balance),
        // while the mutant that does transfer(0) will NOT revert. So we assert that when amount > balance,
        // sendTo must revert (ok==false). This holds for the reference and is violated by the mutant for some inputs.

        bool ok;
        try c.sendTo(address(0xBEEF), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 cBal = address(c).balance;

        // if amount is greater than available balance then the reference MUST revert (ok==false).
        // This is the single assertion that should hold for the reference for all inputs and is broken by the mutant.
        if (amount > cBal) {
            assertTrue(!ok);
        } else {
            // when amount <= balance the call should succeed
            assertTrue(ok);
        }
    }
}
